Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.util.*;
import java.io.*;
public class Text_Document_Analysis
{
    public static void main(String args[]) throws Exception
    {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        // BufferedReader br=new BufferedReader(new FileReader("Text_Document_Analysis.in"));
        br.readLine();
        String line=br.readLine();
        String[] parts=line.split("\\([a-zA-Z_]*\\)");
        int maxWord=0;
        for(String part: parts)
        {
            String[] words=part.split("_+");
            for(String word: words)
                maxWord=Math.max(maxWord, word.length());
        }
        int countInParentheses=0;
        int tempCount=0;
        boolean inParen=false;
        boolean counted=false;
        for(int i=0; i<line.length(); i++)
        {
            char ch=line.charAt(i);
            if(ch=='(')
                inParen=true;
            if(ch==')')
            {
                counted=false;
                inParen=false;
            }
            if(inParen && Character.isLetter(ch))
            {
                if(counted) continue;
                countInParentheses++;
                counted=true;
            }
            if(ch=='_')
                counted=false;
        }
        System.out.println(maxWord+" "+countInParentheses);
    }
}
